class NoteStore:
    def __init__(self):
        self.items = {}
        self.counter = 0

    def next_id(self):
        self.counter += 1
        return self.counter

    def save(self, note_id, title):
        self.items[note_id] = title

    def load(self, note_id):
        return self.items.get(note_id)

